public class IdempotentOrderProcessor {
    private final JdbcTemplate jdbcTemplate;

    public IdempotentOrderProcessor(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    @Transactional
    public void processOrder(String transactionId, OrderPayload order) {
        String checkSql = "SELECT COUNT(1) FROM processed_transactions WHERE transaction_id = ?";
        Integer count = jdbcTemplate.queryForObject(checkSql, Integer.class, transactionId);

        if (count != null && count > 0) {
            return;
        }

        String insertOrder = "INSERT INTO orders (order_id, item, amount) VALUES (?, ?, ?)";
        jdbcTemplate.update(insertOrder, order.getId(), order.getItem(), order.getAmount());

        String recordTx = "INSERT INTO processed_transactions (transaction_id) VALUES (?)";
        jdbcTemplate.update(recordTx, transactionId);
    }
}
